draw(shift(12,0)*((4,0)--(4,10)^^(8,0)--(8,10)));
draw((0,i*10)--(80,i*10)); ++i;

fill((4,0)--(4,20)--(8,20)--(8,0)--cycle,purple);
draw((4,0)--(4,20));
draw((8,0)--(8,20));

for(i = 3; i <= 4; ++i)
{
draw((0,i*10)--(80,i*10));
}

fill(shift(24,0)*((4,0)--(4,35)--(8,35)--(8,0)--cycle),purple);
draw(shift(24,0)*((4,0)--(4,35)^^(8,0)--(8,35)));
draw((0,i*10)--(80,i*10)); ++i;

